#include <iostream>
#include <string>
struct LargeObject {
  std::string data;  // potentially large data member
  LargeObject() = default;
  LargeObject(const std::string& s): data(s) {}
  LargeObject(LargeObject&& other) noexcept : data(std::move(other.data)) {} 
  LargeObject(const LargeObject& other) : data(other.data) {}
};

LargeObject createLargeObject() {
  return LargeObject("This is a large object");
}

int main() {
  LargeObject obj = createLargeObject();
  std::cout << obj.data << std::endl;
  return 0;
}
